// Author: abhinavkumarrath #include <bits/stdc++.h>using namespace std; #pragma GCC optimize("O3,unroll-loops")#pragma GCC target("avx2,bmi,bmi2,lzcnt,popcnt") using ll = long long;using vi = vector<int>;using vll = vector<ll>;using pii = pair<int, int>; #define pb push_back#define all(x) (x).begin(), (x).end()#define sz(x) (int)(x).size()#define fi first#define se second#define rep(i, a, b) for (int i = (a); i < (b); ++i)#define forn(i, n) rep(i, 0, n)#define per(i, a, b) for (int i = (b) - 1; i >= (a); --i)#define rofn(i, n) per(i, 0, n) template<class T> bool chmin(T& a, const T& b) { if (b < a) { a = b; return 1; } return 0; }template<class T> bool chmax(T& a, const T& b) { if (a < b) { a = b; return 1; } return 0; } void yes() { cout << "YES\n"; }void no() { cout << "NO\n"; } const int INF = 1e9;const ll LINF = 1e18; void solve() {    int y, w;    if (!(cin >> y >> w)) return;        int max_roll = max(y, w);    int dot_wins = 6 - max_roll + 1;    int divisor = std::gcd(dot_wins, 6);        cout << (dot_wins / divisor) << "/" << (6 / divisor) << "\n";} int main() {    ios_base::sync_with_stdio(false);    cin.tie(nullptr);        int t = 1;    while (t--) {        solve();    }        return 0;}